  neblina: { categoria: "Clima", palavras: ["neblina", "horizontal", "fog", "lines"], descricao: "Quatro barras horizontais preenchidas com pontas arredondadas empilhadas paralelamente, de larguras levemente diferentes e desalinhadas entre si — representa neblina, névoa ou tempo nublado.", versao: "1.4.0" },
