  nestle: { categoria: "Comida", palavras: ["nestle"], descricao: "Logotipo da marca Nestle em silhueta monocromática preenchida — marca de alimentos/bebidas ou rede de fast-food. Marca registrada. (busque por \"nestle\" ou pelo nome da empresa)", versao: "1.4.0", marca: true },
  netflix: { categoria: "Multimídia", palavras: ["netflix", "the", "logo"], descricao: "Logotipo da marca Netflix em silhueta monocromática preenchida — serviço de streaming de filmes e séries. Marca registrada. (busque por \"netflix\" ou pelo nome da empresa)", versao: "1.4.0", marca: true },
  neve: { categoria: "Clima", palavras: ["neve", "cloud", "with", "snowflakes"], descricao: "Silhueta preenchida de uma nuvem arredondada no topo, sob a qual caem cinco flocos de neve desenhados em contorno de asterisco de seis pontas espalhados abaixo — representa neve ou clima com nevasca.", versao: "1.4.0" },
