  nodejs: { categoria: "Desenvolvimento", palavras: ["nodejs", "the", "hexagon", "logo"], descricao: "Logotipo da marca Nodejs em silhueta monocromática preenchida — marca conhecida. Marca registrada. (busque por \"nodejs\" ou pelo nome da empresa)", versao: "1.4.0", marca: true },
  nomad: { categoria: "Bancos", palavras: ["banco", "digital", "dolar", "internacional", "nomad"], descricao: "Formato de uma letra estilizada composta por barras verticais de cantos arredondados de alturas diferentes ligadas por uma diagonal grossa que atravessa de baixo à esquerda até o topo à direita, tudo preenchido — logotipo do HashiCorp Nomad.", versao: "1.0.0" },
  'nota-dinheiro': { categoria: "Financeiro", palavras: ["nota", "dinheiro", "stack", "banknotes"], descricao: "Silhueta preenchida de várias cédulas de dinheiro empilhadas em perspectiva diagonal, formando um losango achatado com uma marca oval no centro da nota superior e as bordas das notas seguintes visíveis por baixo — representa dinheiro em espécie ou maço de notas.", versao: "1.4.0" },
