  'notas-fiscais': { categoria: "Documentos", palavras: ["fiscais", "notas"], descricao: "Retângulo vertical em pé preenchido de cantos arredondados (folha/documento), com várias linhas horizontais vazadas dentro — uma curta no topo e três longas embaixo — simulando texto — representa uma nota fiscal ou recibo.", versao: "1.0.0" },
