  noticias: { categoria: "Documentos", palavras: ["noticias"], descricao: "Retângulo em contorno representando uma folha de jornal, com uma pequena aba dobrada no canto superior direito; dentro há três linhas horizontais preenchidas de comprimentos decrescentes simulando parágrafos de texto — representa notícias ou jornal.", versao: "1.0.0" },
  notion: { categoria: "Tecnologias", palavras: ["notion", "the", "square", "logo"], descricao: "Logotipo da marca Notion em silhueta monocromática preenchida — empresa de tecnologia. Marca registrada. (busque por \"notion\" ou pelo nome da empresa)", versao: "1.4.0", marca: true },
  npm: { categoria: "Tecnologias", palavras: ["biblioteca", "dependencia", "node", "npm", "pacote", "registro", "tech"], descricao: "Retângulo horizontal deitado preenchido contendo três colunas com as letras minúsculas vazadas do nome recortadas em negativo dentro do bloco sólido — logotipo do gerenciador de pacotes npm.", versao: "1.1.0" },
