  nublado: { categoria: "Clima", palavras: ["nublado", "single", "cloud"], descricao: "Silhueta preenchida de uma nuvem fofa formada por lóbulos arredondados sobrepostos com base plana, orientada horizontalmente — representa céu nublado.", versao: "1.4.0" },
