  'nuvem-download': { categoria: "Tecnologias", palavras: ["nuvem", "download", "cloud", "with", "down", "arrow"], descricao: "Contorno em linha de uma nuvem arredondada com base plana, atravessada ao centro por uma seta vertical apontando para baixo — representa download da nuvem.", versao: "1.4.0" },
  'nuvem-sincronizar': { categoria: "Tecnologias", palavras: ["nuvem", "sincronizar", "cloud", "with", "sync", "arrows"], descricao: "Silhueta preenchida de uma nuvem larga contendo ao centro duas setas curvas circulares formando um ciclo, em recorte vazado — representa sincronização com a nuvem.", versao: "1.4.0" },
  'nuvem-upload': { categoria: "Tecnologias", palavras: ["nuvem", "upload", "cloud", "with", "arrow"], descricao: "Contorno em linha de uma nuvem arredondada com base plana, atravessada ao centro por uma seta vertical apontando para cima — representa upload para a nuvem.", versao: "1.4.0" },
  nuxt: { categoria: "Tecnologias", palavras: ["framework", "frontend", "javascript", "nuxt", "tech", "tech-nuxt", "vue"], descricao: "Montanha estilizada formada por dois triângulos apontando para cima que se sobrepõem, com um recorte em V vazado no centro criando o contorno de picos — logotipo do framework Nuxt.", versao: "1.0.0" },
  nvidia: { categoria: "Tecnologias", palavras: ["nvidia"], descricao: "Logotipo da marca Nvidia em silhueta monocromática preenchida — fabricante de placas de vídeo e chips de IA. Marca registrada. (busque por \"nvidia\" ou pelo nome da empresa)", versao: "1.4.0", marca: true },
