  ondas: { categoria: "Clima", palavras: ["ondas"], descricao: "Três traços curvos e sinuosos preenchidos, em forma de chamas ou línguas onduladas, dispostos lado a lado com alturas crescentes da esquerda para a direita — representa ondas, vibração ou sinal ondulado.", versao: "1.0.0" },
  onibus: { categoria: "Veículos", palavras: ["bus", "coletivo", "onibus", "transporte", "veiculo"], descricao: "Silhueta preenchida de um ônibus visto de perfil e voltado para a esquerda, com frente arredondada e carroceria comprida e reta; ao longo da lateral, uma fileira de janelas retangulares vazadas em contorno e duas rodas circulares grandes na base — representa um ônibus de transporte coletivo.", versao: "1.0.0" },
