  vscode: { categoria: "Tecnologias", palavras: ["code", "editor", "ide", "microsoft", "programacao", "tech", "vscode"], descricao: "Logotipo preenchido do Visual Studio Code: uma fita/formato angular azul que se dobra formando duas pontas em seta apontando uma para dentro da outra, com um bloco vertical à direita representando a barra lateral — é o ícone do editor VS Code.", versao: "1.3.0" },
  vue: { categoria: "Desenvolvimento", palavras: ["vue", "the", "vuejs", "triangle", "logo"], descricao: "Logotipo da marca Vue em silhueta monocromática preenchida — marca conhecida. Marca registrada. (busque por \"vue\" ou pelo nome da empresa)", versao: "1.4.0", marca: true },
  vulcao: { categoria: "Natureza", palavras: ["vulcao", "erupting", "volcano"], descricao: "Silhueta triangular preenchida de um vulcão com base larga e topo achatado com cratera aberta, de onde jorram para cima chamas e labaredas irregulares, além de linhas de fumaça saindo do cume — representa um vulcão em erupção.", versao: "1.4.0" },
