  webhook: { categoria: "Desenvolvimento", palavras: ["webhook", "connector", "symbol"], descricao: "Símbolo vertical em quatro segmentos empilhados centralizados: um traço curto no topo, uma barra retangular fina, um retângulo maior com cantos arredondados ao centro e outro traço na base, conectados como elos de um conector — representa um webhook ou ponto de integração/conexão.", versao: "1.4.0" },
