  whatsapp: { categoria: "Redes Sociais", palavras: ["chat", "contato", "mensagem", "whatsapp", "zap"], descricao: "Balão de conversa arredondado desenhado em contorno com uma pequena aba/rabinho no canto inferior esquerdo, contendo internamente um fone de telefone preenchido — é o logotipo do WhatsApp.", versao: "1.0.0" },
  'whatsapp-ia': { categoria: "Redes Sociais", palavras: ["ia", "whatsapp"], descricao: "Balão de conversa arredondado em contorno com a aba inferior esquerda (silhueta do WhatsApp) contendo, centralizada, uma estrela/brilho de quatro pontas côncavas preenchida — representa o WhatsApp integrado com inteligência artificial.", versao: "1.0.0" },
  wifi: { categoria: "Interface", palavras: ["wifi"], descricao: "Três arcos concêntricos preenchidos abrindo-se para cima como ondas de sinal, do menor ao maior, com um ponto/círculo sólido na base ao centro — representa conexão Wi-Fi ou sinal de rede sem fio.", versao: "1.0.0" },
