  wise: { categoria: "Bancos", palavras: ["banco", "cambio", "internacional", "transferencia", "wise"], descricao: "Logotipo preenchido da Wise: duas setas anguladas em ziguezague empilhadas (formando um símbolo de câmbio/fluxo que aponta para direções opostas) com recortes internos — é o ícone da fintech Wise (antiga TransferWise).", versao: "1.0.0" },
