  x: { categoria: "Interface", palavras: ["cancelar", "close", "erro", "fechar", "remover", "sair", "x"], descricao: "Duas barras diagonais grossas preenchidas cruzando-se em X que preenche toda a área, cada barra com as pontas levemente arredondadas — representa fechar, cancelar ou erro.", versao: "1.0.0" },
