  'x-redondo': { categoria: "Interface", palavras: ["redondo", "x"], descricao: "Círculo sólido preenchido com um X vazado (recorte even-odd) formado por duas linhas finas cruzadas no centro — representa fechar, remover ou marcar como incorreto dentro de um botão redondo.", versao: "1.0.0" },
  'x-twitter': { categoria: "Redes Sociais", palavras: ["x", "twitter"], descricao: "Logotipo da marca X Twitter em silhueta monocromática preenchida — marca / plataforma digital. Marca registrada. (busque por \"x-twitter\" ou pelo nome da empresa)", versao: "1.4.0", marca: true },
  xbox: { categoria: "Tecnologias", palavras: ["xbox", "the", "sphere", "logo"], descricao: "Logotipo da marca Xbox em silhueta monocromática preenchida — empresa de tecnologia. Marca registrada. (busque por \"xbox\" ou pelo nome da empresa)", versao: "1.4.0", marca: true },
  xiaomi: { categoria: "Tecnologias", palavras: ["xiaomi"], descricao: "Logotipo da marca Xiaomi em silhueta monocromática preenchida — empresa de tecnologia. Marca registrada. (busque por \"xiaomi\" ou pelo nome da empresa)", versao: "1.4.0", marca: true },
  xp: { categoria: "Bancos", palavras: ["banco", "corretora", "investimento", "xp"], descricao: "Monograma preenchido das letras X e P estilizadas justapostas dentro de um quadrado de cantos arredondados (moldura com recortes even-odd) — é o logotipo da XP (XP Investimentos).", versao: "1.0.0" },
  yoga: { categoria: "Educação", palavras: ["yoga"], descricao: "Silhueta preenchida de uma pessoa sentada em posição de meditação/lótus vista de frente, cabeça circular no topo, braços curvados apoiados nos joelhos e pernas cruzadas formando uma base larga triangular — representa yoga, meditação ou bem-estar.", versao: "1.0.0" },
  youtube: { categoria: "Redes Sociais", palavras: ["youtube"], descricao: "Retângulo horizontal de cantos bem arredondados preenchido (a tela) com um triângulo vazado apontando para a direita ao centro (botão play) por recorte — é o logotipo do YouTube.", versao: "1.0.0" },
  zara: { categoria: "Redes Sociais", palavras: ["zara"], descricao: "Logotipo da marca Zara em silhueta monocromática preenchida — marca / plataforma digital. Marca registrada. (busque por \"zara\" ou pelo nome da empresa)", versao: "1.4.0", marca: true },
  'zoom-mais': { categoria: "Ações", palavras: ["mais", "zoom"], descricao: "Lupa preenchida inclinada com a lente circular no alto à esquerda e o cabo diagonal na base à direita; dentro da lente, um sinal de mais formado por duas barras cruzadas — representa aproximar/ampliar (zoom in).", versao: "1.0.0" },
